import { count, increment } from "./counter.js";
print(count);
increment();
print(count);

export let count = 0;
export function increment() {
  count += 1;
}

import { fromA } from "./b.js";
export function getA() {
  return "A";
}
export const result = fromA;

import { valueB } from "./b.js";
export const valueA = "A";
export const observed = valueB;

const React = {
  createElement(tag: string, _props: unknown, child: string) {
    return tag + ":" + child;
  },
};
export const view: string = <section>ok</section>;
print(view);

const callbacks = [];
for (const item of ["a", "b"]) {
  callbacks.push(() => item);
}
export const joined = callbacks.map((callback) => callback()).join(",");
print(joined);

function explode(): never {
  const detail: string = "mapped failure";
  throw new Error(detail);
}
explode();

print(String(this));
print(typeof arguments);
try {
  accidentalGlobal = 1;
} catch (error) {
  print(error.name);
}

